"""Reserve one already-authorized exact evaluation; never submit or issue permission.

Call after resource admission, immediately before submit. The first deadline is
immutable: recovery returns the same event, including an expired deadline.
"""
import json
import time

from rlflow import experiments
from rlflow.store import sha
from tools.r6_recovery import RecoveryError, checked
from tools.r6_job_handoff import no_model_workers
from tools.r6_postrun import stop_paths


def require(condition, reason):
    if not condition:raise RecoveryError('REGISTER_JOB_'+reason)


def register_and_close(journal, spec_pin, store, *, queue_key, free_disk_bytes,
                       purpose='development', refresh_observation=None):
    """Admit, reserve, submit and locally close under the caller's one writer.

    A stale resource observation cannot consume a new live reservation. Once a
    submission claim exists, recover its original exact job without demanding a
    new idle-GPU observation of a job that may already be running.
    """
    from tools.r6_submit import queue_ready, submit_and_close
    journal.require_writer()
    spec=json.loads(checked(spec_pin).read_text())
    jid='J-'+sha({'id':spec['id'],'spec':spec})[:16]
    entries=[e for e in journal.read()['events'].values()
             if e['kind']=='job' and e['identity']['job_id']==jid]
    require(len(entries)<=1,'ALIAS')
    if not entries or not entries[0].get('submission_claim'):
        queue_ready(journal,queue_key,spec_pin)
    key=register(journal,spec_pin,store,free_disk_bytes=free_disk_bytes,purpose=purpose)
    result=submit_and_close(journal,key,store,queue_key=queue_key,
                            refresh_observation=refresh_observation)
    return dict(event_key=key,**result)


def register(journal, spec_pin, store, *, free_disk_bytes, purpose='development'):
    journal.require_writer()
    state=journal.read();spec=json.loads(checked(spec_pin).read_text())
    jid='J-'+sha({'id':spec['id'],'spec':spec})[:16]
    existing=[(k,e) for k,e in state['events'].items()
              if e['kind']=='job' and e['identity']['job_id']==jid]
    if existing:
        require(len(existing)==1,'ALIAS')
        key,entry=existing[0];request=entry['request'];identity=entry['identity']
        expected=dict(goal_id=state['goal_id'],event_id='JOB:'+jid,job_id=jid,
                      input_sha256=sha(request),role='job')
        require(identity==expected and sha(identity)==key and entry['purpose']==purpose
                and set(request)=={'spec','wait_deadline_unix'} and request['spec']==spec_pin,
                'REPLAY_DRIFT')
        reservation_key=json.dumps(tuple(identity[k] for k in sorted(identity)),separators=(',',':'))
        reservations=[r for r in state['budget']['reservations']
                      if r['identity']==identity or r['event_key']==reservation_key]
        require(state['budget']['goal_id']==state['goal_id'] and len(reservations)==1
            and reservations[0]['identity']==identity and reservations[0]['event_key']==reservation_key
            and reservations[0]['resources']==entry['resources'] and reservations[0]['purpose']==purpose,
            'RESERVATION_DRIFT')
        from tools.r6_storage_allocation import owner
        owner(journal,entry)
        return key
    journal.guard();require(not stop_paths(journal),'STOP')
    require(state['budget']['capacity_pass'] is True,'CAPACITY_NOT_ACCEPTED')
    require(state.get('current_job') is None,'JOB_ACTIVE')
    no_model_workers(journal)
    require(jid not in store.replay()['jobs'],'EXISTING_STORE_JOB')
    experiments.validate(spec,store.root)
    experiments.authorized(store.replay(),spec,store.root)
    from tools.r6_storage_allocation import for_spec
    storage=for_spec(journal,spec_pin,purpose=purpose,bind_new=True)
    resources=dict(live_starts=1,live_wall_seconds=spec['resources']['wall_seconds']+180,
                   allocated_gpu_seconds=spec['resources']['wall_seconds']+180)
    if spec['backend']=='real':
        require(spec.get('h1',{}).get('mode')=='research-r6-evaluation','R6_MODE_REQUIRED')
        auth=json.loads(checked(spec['pins']['authorization']).read_text())
        resources.update(simulator_initializations=1,
            nontraining_transitions=spec['resources']['transitions'],
            output_actual_plus_unreleased_reservations_bytes=0 if storage is not None else auth['parameters']['output_cap_bytes'])
    else:
        require(spec['backend']=='runner_cpu' and state['goal_id']=='R6-CPU-TEST-FIXTURE','CPU_FIXTURE_BOUNDARY')
        resources['output_actual_plus_unreleased_reservations_bytes']=1024**2
    require(not stop_paths(journal),'STOP')
    request=dict(spec=spec_pin,wait_deadline_unix=time.time()+spec['resources']['wall_seconds'])
    event=dict(goal_id=state['goal_id'],event_id='JOB:'+jid,job_id=jid,input_sha256=sha(request),role='job')
    key,_=journal.intent(event,kind='job',request=request,resources=resources,
        purpose=purpose,free_disk_bytes=free_disk_bytes)
    return key
"""CPU-only R6 budget checks. Caller holds the single controller writer lock.

No Store permission, submission, settlement or budget refund occurs here.
Reservations remain charged even when an attempt or worker fails.
"""
import copy
import math


class BudgetError(ValueError):
    pass


def amount(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise BudgetError('Resource amount must be numeric')
    if not math.isfinite(value) or value < 0:
        raise BudgetError('Resource amount must be finite and nonnegative')
    return value


def charged(reservation, caps):
    """Conservative charge: max(reserved, every pinned observation), never sum twice."""
    result = {}
    for resources in [reservation['resources'], *[o['resources'] for o in reservation.get('observations', [])]]:
        for resource, value in resources.items():
            if resource not in caps:
                raise BudgetError('Unknown resource: ' + resource)
            result[resource] = max(result.get(resource, 0), amount(value))
    return result


def totals(ledger, *, enforce_caps=True):
    caps = ledger['caps']
    result = {k: amount(ledger['used'][k]) for k in caps}
    seen = set()
    for reservation in ledger['reservations']:
        key = reservation['event_key']
        if key in seen:
            raise BudgetError('Duplicate reservation event')
        seen.add(key)
        for resource, value in charged(reservation, caps).items():
            result[resource] += value
    for resource, value in result.items():
        if enforce_caps and value > amount(caps[resource]):
            raise BudgetError('Cap exceeded: ' + resource)
    return result


def admissible(ledger):
    """Current hard and protected limits; also required before a first dispatch."""
    usage = totals(ledger)
    for resource, protected in ledger['protected_confirmation_delivery_repair'].items():
        # Protected use cannot accidentally become available to exploration.
        dev_used = amount(ledger['used'][resource])
        dev_used += sum(charged(r, ledger['caps']).get(resource, 0) for r in ledger['reservations']
                        if r['purpose'] == 'development')
        if dev_used > ledger['caps'][resource] - amount(protected):
            raise BudgetError('Protected capacity: ' + resource)
    model_cap = ledger['caps']['automatic_model_sessions']
    other_models = amount(ledger['used']['automatic_model_sessions']) + sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                       for r in ledger['reservations']
                       if r['purpose'] not in {'repair', 'final_review'})
    if other_models > model_cap - sum(ledger['protected_model_sessions'].values()):
        raise BudgetError('Protected review/repair sessions')
    for protected_role, count in ledger['protected_model_sessions'].items():
        outside_role = amount(ledger['used']['automatic_model_sessions'])
        outside_role += sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                            for r in ledger['reservations']
                            if r['purpose'] != protected_role)
        if outside_role > model_cap - count:
            raise BudgetError('Protected model role: ' + protected_role)
    return usage


def reserve(ledger, *, event_key, resources, purpose, free_disk_bytes):
    """Return a new ledger; identical replays don't spend again, drift fails.

    event_key binds goal, event, job, input hash and role. Final/recovery use
    of protected capacity is explicit. Ordinary development cannot borrow it.
    Disk check subtracts all outstanding output reservations conservatively.
    """
    required = {'goal_id', 'event_id', 'job_id', 'input_sha256', 'role'}
    if set(event_key) != required or event_key['goal_id'] != ledger['goal_id']:
        raise BudgetError('Incomplete event identity')
    if not all(isinstance(v, str) and v for v in event_key.values()):
        raise BudgetError('Empty event identity')
    digest = event_key['input_sha256']
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
        raise BudgetError('Invalid input hash')
    if purpose not in {'development', 'confirmation_delivery', 'repair', 'final_review'}:
        raise BudgetError('Unknown reservation purpose')
    key = tuple(event_key[k] for k in sorted(required))
    # JSON round trips preserve this stable string; tuples are not persisted.
    import json
    key = json.dumps(key, separators=(',', ':'))
    entry = {'event_key': key, 'identity': event_key, 'resources': resources, 'purpose': purpose}
    for prior in ledger['reservations']:
        if prior['event_key'] == key:
            if {k: prior[k] for k in entry} != entry:
                raise BudgetError('Reservation replay drift')
            admissible(ledger)
            return copy.deepcopy(ledger)
    candidate = copy.deepcopy(ledger)
    candidate['reservations'].append(copy.deepcopy(entry))
    usage = admissible(candidate)
    disk_key = 'output_actual_plus_unreleased_reservations_bytes'
    if amount(free_disk_bytes) - usage[disk_key] < ledger['disk_free_floor_bytes']:
        raise BudgetError('Disk floor after reservations')
    return candidate


def observe(ledger, *, event_key, resources, evidence):
    """Record pinned actuals, including overruns; never mutate/refund reservations.

    Actual cap breaches must be durable even though further reserve() will fail.
    Caller verifies evidence bytes and atomically saves this result with its event.
    """
    if (not isinstance(evidence, dict) or set(evidence) != {'path', 'sha256'}
            or not isinstance(evidence['path'], str) or not evidence['path']
            or not isinstance(evidence['sha256'], str) or len(evidence['sha256']) != 64
            or any(c not in '0123456789abcdef' for c in evidence['sha256'])):
        raise BudgetError('Observation evidence pin')
    if not isinstance(resources, dict) or not resources:
        raise BudgetError('Observation resources required')
    charged({'resources': resources}, ledger['caps'])
    result = copy.deepcopy(ledger)
    entries = [r for r in result['reservations'] if r['identity'] == event_key]
    if len(entries) != 1:
        raise BudgetError('Observation requires one exact reservation')
    observations = entries[0].setdefault('observations', [])
    new = {'resources': copy.deepcopy(resources), 'evidence': copy.deepcopy(evidence)}
    for old in observations:
        if old['evidence'] == evidence:
            if old != new:
                raise BudgetError('Observation replay drift')
            return result
    observations.append(new)
    usage = totals(result, enforce_caps=False)
    result['observed_cap_excess'] = {k: v-result['caps'][k] for k, v in usage.items() if v > result['caps'][k]}
    return result
"""Exact experiment approvals and a durable adapter to the reviewed H1 dispatcher.

runner_cpu uses the real held-child dispatcher with an isolated CPU workload.
real uses the same code but needs its own exact proposal; fake evidence never
confers real authorization. No default training allowance exists.
"""
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import subprocess
import sys
import time
from .store import Conflict, canonical, atomic, sha, Store
from .policy import stopped, STOP_PATHS
from .jobs import identity, owns, _kill_owned

DISPATCHER = Path('/home/mint/rl_dev/instinctRL-dev/training_workloads/unified_h1/local_dispatch.py')


def file_pin(path):
    p=Path(path).resolve(strict=True)
    if not p.is_file(): raise Conflict('input pin must be a file')
    return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}


def check_pins(spec):
    for name,pin in spec['pins'].items():
        if not isinstance(pin,dict) or set(pin)!={'path','sha256'} or file_pin(pin['path'])!=pin:
            raise Conflict('experiment input drift: '+name)
    # Immutable candidate snapshots use a different path to the same reviewed bytes.
    if spec['pins']['dispatcher']['sha256']!=file_pin(DISPATCHER)['sha256']:
        raise Conflict('experiment must use the reviewed H1 dispatcher')


def validate(spec, root):
    required={'id','stage_id','backend','argv','cwd','pins','method','evaluation','runtime','seed','resources','conditions','observations'}
    if not isinstance(spec,dict) or not required<=set(spec) or set(spec)-required-{'h1'}:raise Conflict('complete experiment specification required')
    if spec['backend'] not in {'runner_cpu','real'}:raise Conflict('unsupported experiment backend')
    for key in ('id','stage_id','method','evaluation','runtime'):
        if not isinstance(spec[key],str) or not spec[key].strip():raise Conflict('experiment identity missing: '+key)
    if type(spec['seed']) is not int:raise Conflict('fixed integer seed required')
    if not isinstance(spec['argv'],list) or not spec['argv'] or any(not isinstance(x,str) for x in spec['argv']):raise Conflict('invalid argv')
    if set(spec['pins'])!={'dispatcher','executable','product','workload','runtime','authorization'}:raise Conflict('all exact input pins required')
    check_pins(spec)
    if spec['argv'][0]!=spec['pins']['executable']['path']:raise Conflict('executable binding mismatch')
    resources=spec['resources']
    if not isinstance(resources,dict) or set(resources)!={'starts','wall_seconds','gpu_seconds','transitions'}:raise Conflict('explicit resource dimensions required')
    if resources['starts']!=1 or any(type(v) is not int or v<0 for v in resources.values()) or not 1<=resources['wall_seconds']<=86400:raise Conflict('invalid exact experiment resources')
    cwd=Path(spec['cwd']).resolve(strict=True)
    if not cwd.is_dir():raise Conflict('invalid working directory')
    if spec['backend']=='runner_cpu':
        if resources['gpu_seconds'] or resources['transitions'] or not cwd.is_relative_to(Path(root)/'workspaces'):
            raise Conflict('CPU adapter cannot access training resources')
    if not isinstance(spec['conditions'],list) or not spec['conditions']:raise Conflict('explicit structured conditions required')
    for c in spec['conditions']:
        if not isinstance(c,dict) or set(c)!={'evidence_id','sha256'}:raise Conflict('only accepted evidence hash predicates supported')
    if not isinstance(spec['observations'],list) or not spec['observations'] or any(not isinstance(x,str) or not x for x in spec['observations']):raise Conflict('required observations missing')
    if spec['backend']=='real':
        from .h1 import validate as validate_h1
        validate_h1(spec,root)
    elif 'h1' in spec:raise Conflict('CPU substitute cannot carry real H1 authority')
    return spec


def propose(store,spec):
    validate(spec,store.root)
    content={'scope':'EXPERIMENT','stage_id':spec['stage_id'],'spec':spec,
             'budget':{'role_calls':0,'wall_seconds':spec['resources']['wall_seconds'],'fake_starts':0},
             'preconditions':['exact pins','accepted condition hashes','STOP clear','single submission']}
    digest=sha(content);pid='P-'+digest[:16]
    def change(s):
        for old in s['proposals'].values():
            if old['content'].get('scope')=='EXPERIMENT' and old['content']['spec']['id']==spec['id'] and old['sha256']!=digest:
                raise Conflict('experiment ID already binds another immutable specification')
        s['proposals'][pid]={'id':pid,'version':1,'sha256':digest,'content':content,'shown':False}
    store.transact('PROPOSAL_CREATED','proposal:'+digest,change,object_id=pid)
    atomic(store.root/'proposals'/(pid+'.json'),canonical(content));return pid


def authorized(s,spec,root):
    package=s.get('packages',{}).get(spec['stage_id'])
    autonomous=package and package['status']=='ACTIVE' and not package['paused'] and any(t in s.get('autonomous_tasks',[]) for t in package['tasks'])
    if (s['paused'] and not autonomous) or stopped(root):raise Conflict('paused or STOP')
    if s.get('stages',{}).get(spec['stage_id'],{}).get('status')=='REVOKED':raise Conflict('underlying stage revoked')
    check_pins(spec)
    if spec['backend']=='real':
        from .h1 import validate as validate_h1
        validate_h1(spec,root)
    matches=[]
    for a in s['approvals'].values():
        p=s['proposals'][a['proposal_id']];c=p['content']
        if c.get('scope')=='EXPERIMENT' and c.get('spec')==spec:
            if (a['decision']=='APPROVED' and not a.get('revoked') and not p.get('revoked')
                    and sha(c)==a['proposal_sha256']==p['sha256'] and a['proposal_version']==p['version']):matches.append(a)
    if package and spec in package['spec'].get('experiments',[]):
        from .packages import require_package
        require_package(s,s['stages'][spec['stage_id']])
        matches.append({'approval_id':package['approval_id']+':experiment:'+sha(spec)})
    if len(matches)!=1:raise Conflict('no unique exact experiment approval')
    for c in spec['conditions']:
        e=s['evidence'].get(c['evidence_id'],{})
        if not e.get('accepted') or e.get('sha256')!=c['sha256']:raise Conflict('conditional authorization unmet or drifted')
    return matches[0]


def submit(store,spec):
    jid='J-'+sha({'id':spec['id'],'spec':spec})[:16]
    existing=store.replay()['jobs'].get(jid)
    if existing:
        if existing['spec']!=spec:raise Conflict('experiment identity collision')
        return reconcile(store,jid)
    validate(spec,store.root)
    launched=[]
    def reserve(s):
        approval=authorized(s,spec,store.root)
        if any(j.get('spec',{}).get('backend') in {'real','runner_cpu'} and j['status'] in {'START_INTENT','RUNNING','RECONCILE'} for j in s['jobs'].values()):
            raise Conflict('another runner job owns the execution slot')
        if any(j.get('approval_id')==approval['approval_id'] for j in s['jobs'].values()):raise Conflict('experiment approval already consumed')
        s['jobs'][jid]={'id':jid,'stage':spec['stage_id'],'spec':spec,'approval_id':approval['approval_id'],
                        'status':'START_INTENT','reserved_resources':spec['resources'],'used_resources':{},'identity':None}
        launched.append(True)
    state=store.transact('EXPERIMENT_RESERVED',jid+':reserve',reserve,object_id=jid)
    if not launched:return reconcile(store,jid)
    d=store.root/'jobs'/jid;d.mkdir(parents=True,exist_ok=True)
    atomic(d/'request.json',canonical({'root':str(store.root),'job_id':jid,'spec':spec}))
    if spec['backend']=='real':
        from .h1 import validate as validate_h1
        atomic(d/'h1-authority.json',canonical(validate_h1(spec,store.root)))
    from .releases import freeze
    frozen=freeze(store.root/'session_releases')
    with (d/'supervisor.log').open('ab') as log:
        proc=subprocess.Popen([sys.executable,'-m','rlflow.experiments','_worker',str(d/'request.json')],cwd=frozen,stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True)
    ident=identity(proc.pid)
    store.transact('EXPERIMENT_IDENTITY',jid+':identity',lambda s:s['jobs'][jid].update(identity=ident,status='RUNNING'),object_id=jid)
    try:
        authorized(store.replay(),spec,store.root)
        atomic(d/'supervisor-release.json',canonical({'job_id':jid,'identity':ident,'control_release':frozen.name}))
    except Conflict:
        atomic(d/'cancel',b'authorization changed before supervisor release')
    return store.replay()['jobs'][jid]


def status(store,jid):return store.replay()['jobs'][jid]
def show_proposal(store, pid):
    p = store.replay()["proposals"][pid]
    if sha(p["content"]) != p["sha256"]:
        raise Conflict("proposal hash mismatch")
    store.transact("PROPOSAL_SHOWN", "shown:" + p["sha256"], lambda s: s["proposals"][pid].update(shown=True), object_id=pid, producer="user-cli")
    return {"proposal_id": pid, "sha256": p["sha256"], "content": p["content"]}


def decide(store, pid, digest, decision, reason):
    if decision not in {"APPROVED", "REJECTED"}:
        raise Conflict("invalid approval decision")
    def mutate(s):
        p = s["proposals"][pid]
        if not p["shown"] or sha(p["content"]) != digest or p["sha256"] != digest:
            raise Conflict("must show and approve exact proposal sha256")
        c = p["content"]
        aid = "A-" + digest[:16]
        if aid in s["approvals"]:
            raise Conflict("decision already recorded; use explicit revocation for an approval")
        if decision == "APPROVED" and c["scope"] in {"SANDBOX_ONLY","MAINLINE_ADOPTION"}:
            from .adoption import approve_in
            approve_in(s,c,aid)
        elif decision == "APPROVED" and c["scope"] == "PACKAGE":
            from .packages import approve_in
            approve_in(s, c, aid, digest)
        elif decision == "APPROVED" and c["scope"] == "STAGE":
            if candidate(c["repo"]) != c["baseline"]:
                raise Conflict("candidate changed since proposal; create a new proposal")
            if c["stage_id"] in s["stages"]:
                raise Conflict("stage exists; cannot reset cumulative budget")
            s["stages"][c["stage_id"]] = new_stage(
                c["stage_id"], c["repo"], c["task"], c["budget"], digest,
                approval_id=aid, module_roots=c["module_roots"],
                protected_paths=c["protected_paths"], cpu_runtime=c.get("cpu_runtime"))
        elif decision == "APPROVED" and c["scope"] == "STAGE_EXTENSION":
            stage = require_stage(s, c["stage_id"])
            task = s["tasks"].get(c["task_id"])
            if any(x['stage_id'] == c['stage_id'] and x['status'] in {'START_INTENT','RUNNING','RECONCILE'}
                   for x in s['sessions'].values()):
                raise Conflict('cannot approve extension with an active or uncertain role')
            if (task is None or task["version"] != c["task_version"]
                    or candidate(c["repo"]) != c["candidate"]
                    or stage["budget"] != c["recorded_budget"]
                    or any(stage[k] != c["recorded_usage"][k] for k in c["recorded_usage"])):
                raise Conflict("stage, task, usage, or candidate changed since extension proposal")
            additional = c["additional_budget"]
            for key in ("role_calls", "wall_seconds", "fake_starts"):
                stage["budget"][key] += additional[key]
            stage["compute"]["limits"]["sol"] += c["additional_compute"]["sol"]
            stage["compute"]["limits"]["astra"] += c["additional_compute"]["astra"]
            stage.setdefault("approval_extensions", []).append(aid)
            task.update(status="QUEUED", next_role=c['next_role'], accepted_candidate=c["candidate"],
                        version=task["version"] + 1)
            task.pop("last_failure", None)
            task.pop("last_error", None)
        s["approvals"][aid] = {"approval_id": aid, "proposal_id": pid, "proposal_version": p["version"],
                              "proposal_sha256": digest, "decision": decision, "approver": "local-user-cli",
                              "time": time.time(), "reason": reason, "scope": c["scope"], "stage_id": c["stage_id"],
                              "budget": c.get("budget", c.get("additional_budget", c.get("package", {}).get("budget"))),
                              "preconditions": c.get("preconditions", ["exact extension binding"])}
        if decision == 'APPROVED' and c.get('execution', {}).get('mode') == 'stage_loop':
            from .engine import create_task
            tid = (create_task(s, store.root, c['stage_id'], c['task'])
                   if c['scope'] == 'STAGE' else c['task_id'])
            selected = s.setdefault('autonomous_tasks', [])
            if tid not in selected:
                selected.append(tid)
    return store.transact("APPROVAL_RECORDED", "decision:" + digest + ":" + decision, mutate, producer="user-cli", object_id=pid)
